        identity.put("testItem", testItem);
        identity.put("meanMin", req.meanMin().trim());
        identity.put("meanMax", req.meanMax().trim());
        identity.put("maxRange", req.maxRange().trim());
        identity.put("expectedVersion", req.expectedVersion());
