// ---------- 新轮使旧批准失效 ----------

@Test
void newRound_invalidatesOldApprovals() throws Exception {
    String batchKey = "BK-ASSAY-INV-" + unique();
    createBatch(batchKey, List.of("含量"), 201);
    long round1 = openRound(batchKey, "RQ-O1", "含量", "op-1", 0, "9", "11", "0.2", 201);
