    approve(batchKey, "qa-1", "QUALITY", "CK-AQ", 201);
    assertEquals("RELEASE_REVIEW", currentStatus(batchKey));

    // 开新轮：批次回退隔离，旧批准失效，不能用旧轮合格授权新轮
    long round2 = openRound(batchKey, "RQ-O2", "含量", "op-1", 1, "9", "11", "0.2", 201);
