    String batchKey = "BK-ASSAY-RACE-" + unique();
    createBatch(batchKey, List.of("含量"), 201);
    long roundId = openRound(batchKey, "RQ-O1", "含量", "op-1", 0, "9", "11", "0.2", 201);

